CREATE TABLE IF NOT EXISTS `level` (
  `level` int(11) NOT NULL,
  `anzahl_karten` int(11) DEFAULT NULL,
  `spielZeit` int(11) DEFAULT NULL,
  `xp` int(11) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


