ALTER TABLE `karte`
  ADD PRIMARY KEY (`id`);

ALTER TABLE `level`
  ADD PRIMARY KEY (`level`);


ALTER TABLE `spiel`
  ADD KEY `initiator` (`initiator`),
  ADD KEY `mitspieler` (`mitspieler`),
  ADD KEY `gewinner` (`gewinner`),
  ADD KEY `level` (`level`);

ALTER TABLE `spieler`
  ADD PRIMARY KEY (`id`),
  ADD KEY `level` (`level`);


ALTER TABLE `karte`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=17;


ALTER TABLE `spieler`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=2;


ALTER TABLE `spiel`
  ADD CONSTRAINT `spiel_ibfk_1` FOREIGN KEY (`initiator`) REFERENCES `spieler` (`id`),
  ADD CONSTRAINT `spiel_ibfk_2` FOREIGN KEY (`mitspieler`) REFERENCES `spieler` (`id`),
  ADD CONSTRAINT `spiel_ibfk_3` FOREIGN KEY (`gewinner`) REFERENCES `spieler` (`id`),
  ADD CONSTRAINT `spiel_ibfk_4` FOREIGN KEY (`level`) REFERENCES `level` (`level`);


ALTER TABLE `spieler`
  ADD CONSTRAINT `spieler_ibfk_1` FOREIGN KEY (`level`) REFERENCES `level` (`level`);
COMMIT;

